    "/api/v1/approvals/bulk": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Run quick actions on several items
         * @description Calls the owning module for each item (approve / return settlements, approve / reject kharcha, send / reject top-ups (owner, `method` needed), approve (= verify) / reject measurements, issue draft invoices (owner), clear / bounce cheques (owner)). reject / return / bounce need a `note`. Items are independent: the answer lists each result; one failure does not undo the others.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": {
                        items: {
                            /** @enum {string} */
                            type: "SETTLEMENT_SUBMITTED" | "EXPENSE_PENDING_APPROVAL" | "TOPUP_PENDING" | "MEASUREMENT_TO_VERIFY" | "SHORTAGE_OPEN" | "PURCHASE_PENDING_RATE" | "STAGE_READY_UNBILLED" | "INVOICE_DRAFT" | "CHEQUE_PENDING";
                            /** Format: uuid */
                            id: string;
                            /** @enum {string} */
                            action: "approve" | "reject" | "return" | "verify" | "issue" | "clear" | "bounce";
                            /** @description Required for reject / return / bounce */
                            note?: string;
                            /**
                             * @description Top-up approve: how the cash is sent
                             * @enum {string}
                             */
                            method?: "CASH" | "BANK" | "JAZZCASH" | "EASYPAISA";
                        }[];
                    };
                };
            };
            responses: {
                /** @description Per-item results */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        /**
                         * @example {
                         *       "success": true,
                         *       "data": {
                         *         "succeeded": 1,
                         *         "failed": 1,
                         *         "results": [
                         *           {
                         *             "type": "EXPENSE_PENDING_APPROVAL",
                         *             "id": "0199a8c0-0000-7000-8000-000000000a41",
                         *             "action": "approve",
                         *             "ok": true,
                         *             "error": null
                         *           },
                         *           {
                         *             "type": "MEASUREMENT_TO_VERIFY",
                         *             "id": "0199a8c0-0000-7000-8000-000000000a51",
                         *             "action": "verify",
                         *             "ok": false,
                         *             "error": {
                         *               "code": "MEASUREMENT_NOT_PENDING",
                         *               "message": "This measurement is already verified"
                         *             }
                         *           }
                         *         ]
                         *       }
                         *     }
                         */
                        "application/json": {
                            /** @enum {boolean} */
                            success: true;
                            data?: unknown;
                        };
                    };
                };
                /** @description VALIDATION_ERROR */
                400: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["ErrorResponse"];
                    };
                };
                /** @description UNAUTHENTICATED | TOKEN_INVALID | TOKEN_EXPIRED | SESSION_REVOKED | ACCOUNT_DISABLED | DEVICE_REVOKED */
                401: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["ErrorResponse"];
                    };
                };
                /** @description FORBIDDEN | COMPANY_SUSPENDED | ACCOUNT_READ_ONLY */
                403: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["ErrorResponse"];
                    };
                };
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
